/**
 * src/data/bmc-ward-boundaries.ts
 *
 * GENERATED from DataMeet's BMC_Wards.geojson (Municipal_Spatial_Data/Mumbai),
 * licensed CC BY-SA 2.5 India - https://github.com/datameet/Municipal_Spatial_Data.
 * The 24 administrative wards in their 2011 structure. Each ward keeps its
 * largest part, simplified (Douglas-Peucker, about 30 m, the coarsest that leaves no two
 * wards overlapping) along each shared
 * border once, so neighbouring wards keep the same edge; `areaSqKm` is the
 * planar area of every part before simplification and `centroid` the area
 * centroid of the largest part. `polygon` is the same outline projected into
 * the 0-100 map space the ward map draws in, one scale on both axes so shapes
 * are true to the ground; `ring` is the outline in [lat, lon].
 */

export interface BmcWardBoundary {
  polygon: Array<[number, number]>
  ring: Array<[number, number]>
  centroid: { lat: number; lng: number }
  areaSqKm: number
}

export const BMC_WARD_BOUNDS: { minLat: number; maxLat: number; minLng: number; maxLng: number } = {minLat: 18.89396, maxLat: 19.27018, minLng: 72.77633, maxLng: 72.97973}

/** Project a [lng, lat] position into the ward map's 0-100 space. */
export function projectToWardMap(lat: number, lng: number): [number, number] {
  return [Math.round((25.3084 + (lng - 72.776333) * 242.7903) * 100) / 100, Math.round((2 + (19.270176 - lat) * 255.1729) * 100) / 100]
}

